    kh, kw = kr1 - kr0 + 1, kc1 - kc0 + 1
    sh, sw = sr1 - sr0 + 1, sc1 - sc0 + 1
    if sh % kh or sw % kw or sh // kh != sw // kw:
        return [row[:] for row in grid]
    scale = sh // kh
    mh, mw = kh, kw

    # The 8-silhouette is a mask of enlarged key-grid cells.
    mask = set()
    for r, c in shape_cells:
        q = (r - sr0, c - sc0)
        if q[0] % scale or q[1] % scale:
            return [row[:] for row in grid]
        mask.add((q[0] // scale, q[1] // scale))
    # Require each macro-cell to be fully present.
    for r, c in mask:
        for dr in range(scale):
            for dc in range(scale):
                if (sr0 + r * scale + dr, sc0 + c * scale + dc) not in shape_cells:
                    return [row[:] for row in grid]

    colors = sorted({grid[r][c] for r, c in key_cells})
    pieces = {}
    for color in colors:
